import numpy as np

def Q_max_correct(n, S):
    res = 0
    for d in range(-n, n + 1):
        x = S - d
        if -1 <= x <= 1:
            if max(0, -d) <= (n - d) // 2:
                km = n if (n - d) % 2 == 0 else n - 1
                if km >= 0:
                    res = max(res, km + x**2)
    return res

def check_n_correct(n):
    for S in np.linspace(-0.99, 0.99, 1000):
        Q = 20 - S**2
        if Q < 0: continue
        Q_min = S**2 / n
        Q_max = Q_max_correct(n, S)
        if Q_min < Q < Q_max:
            return True
    return False

for n in range(19, 25):
    print(f"n={n}: {check_n_correct(n)}")
